    internal func createEmptyStaffSystem(_ index: Double) throws -> StaffSystem {
        let system: StaffSystem = StaffSystem(self)
        system.index = index
        let allFactories: List<BarRendererFactory> = Environment.defaultRenderers
        let renderStaves: List<RenderStaff> = List<RenderStaff>()
        do {
            var trackIndex: Double = 0.0
            while try trackIndex < jsNonNull(self.renderer.tracks).length {
                let track: Track = try jsNonNull(self.renderer.tracks)[(trackIndex).toInt()]
                do {
                    var staffIndex: Double = 0.0
                    while staffIndex < track.staves.length {
                        let staff: Staff = track.staves[(staffIndex).toInt()]
                        var sharedTopEffects: List<EffectBandInfo> = List<EffectBandInfo>()
                        var sharedBottomEffects: List<EffectBandInfo> = List<EffectBandInfo>()
                        var previousStaff: RenderStaff? = nil
                        for factory in allFactories {
                            if self.profile.has(factory.staffId) && factory.canCreate(track, staff) {
                                let renderStaff: RenderStaff = RenderStaff(system, trackIndex, staff, factory)
                                renderStaff.topEffectInfos.splice(0.0, 0.0, contentsOf: sharedTopEffects)
                                renderStaff.bottomEffectInfos.push(contentsOf: sharedBottomEffects)
                                previousStaff = renderStaff
                                renderStaves.push(renderStaff)
                                sharedTopEffects = List<EffectBandInfo>()
                                sharedBottomEffects = List<EffectBandInfo>()
                            } else {
                                for e in factory.effectBands {
                                    switch e.mode {
                                    case EffectBandMode.SharedTop:
                                        sharedTopEffects.push(e)
                                    case EffectBandMode.SharedBottom:
                                        sharedBottomEffects.push(e)
                                    default:
                                        break
                                    }
                                }
                            }
                        }
                        if TypeHelper.isTruthy(previousStaff) {
                            if sharedTopEffects.length > 0 {
                                previousStaff!.bottomEffectInfos.push(contentsOf: sharedTopEffects)
                            }
                            if sharedBottomEffects.length > 0 {
                                previousStaff!.bottomEffectInfos.push(contentsOf: sharedBottomEffects)
                            }
                        }
                        staffIndex += 1
                    }
                }
                trackIndex += 1
            }
        }
        for staff in renderStaves {
            system.addStaff(staff)
        }
        return system
    }

